<?php
require_once __DIR__.'/../repositories/userPDO.php';
function accountFields($name,$email){$name=trim($name);$email=strtolower(trim($email));if($name===''||strlen($name)>120||strlen($email)>254||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Enter a valid name and email.');return [$name,$email];}
function passwordRule($password,$confirm){if(strlen($password)<12||strlen($password)>72||$password!==$confirm)throw new InvalidArgumentException('Use matching passwords of 12 to 72 bytes.');}
function registerUser($pdo,$name,$email,$password,$confirm,$role,$cli=false){[$name,$email]=accountFields($name,$email);passwordRule($password,$confirm);if(!in_array($role,$cli?['Administrator']:['Student','Tutor'],true))throw new InvalidArgumentException('Invalid account type.');$pdo->beginTransaction();try{if(findUserByEmail($pdo,$email))throw new InvalidArgumentException('Email already registered.');$id=insertUser($pdo,$name,$email,password_hash($password,PASSWORD_DEFAULT),$role);if($role==='Student')createStudentLink($pdo,$id,$name,$email);$pdo->commit();return $id;}catch(Throwable $e){$pdo->rollBack();throw $e;}}
function authenticateUser($pdo,$email,$password){$u=findUserByEmail($pdo,trim($email));return $u&&$u['status']==='Active'&&password_verify($password,$u['password_hash'])?$u:false;}
function saveProfile($pdo,$id,$name,$email){[$name,$email]=accountFields($name,$email);$pdo->beginTransaction();try{$other=findUserByEmail($pdo,$email);if($other&&(int)$other['user_id']!==$id)throw new InvalidArgumentException('Email already registered.');updateUserProfile($pdo,$id,$name,$email);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();throw $e;}}
function changePassword($pdo,$id,$current,$new,$confirm){$u=findUserById($pdo,$id);if(!$u||!password_verify($current,$u['password_hash']))throw new InvalidArgumentException('Current password incorrect.');passwordRule($new,$confirm);updateUserPassword($pdo,$id,password_hash($new,PASSWORD_DEFAULT));}
function adminActor($pdo,$id){$u=findUserById($pdo,$id);if(!$u||$u['role']!=='Administrator'||$u['status']!=='Active')throw new InvalidArgumentException('Administrator access required.');}
function changeAccess($pdo,$actor,$id,$role,$status){$pdo->beginTransaction();try{adminActor($pdo,$actor);$u=findUserById($pdo,$id);if(!$u||!in_array($role,['Student','Tutor','Administrator'],true)||!in_array($status,['Active','Inactive'],true))throw new InvalidArgumentException('Invalid account or access values.');if($u['role']==='Administrator'&&$u['status']==='Active'&&($role!=='Administrator'||$status!=='Active')&&activeAdminCount($pdo)<=1)throw new InvalidArgumentException('Keep at least one active administrator.');if($role==='Student'&&!studentForUser($pdo,$id))createStudentLink($pdo,$id,$u['full_name'],$u['email']);updateUserAccess($pdo,$id,$role,$status);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();throw $e;}}
function deleteAccount($pdo,$actor,$id){adminActor($pdo,$actor);if(!findUserById($pdo,$id))throw new InvalidArgumentException('Account not found.');if(relatedRequestCount($pdo,$id))throw new InvalidArgumentException('Deletion blocked by related tutoring records.');throw new InvalidArgumentException('Deletion blocked: retention policy not approved. Use deactivation instead.');}
